import{c as e,Q as a,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"CheckLocalMemoryIA(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"CheckLocalMemoryIA\\\\(ISASI\\\\)","slug":"checklocalmemoryiaisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/调试接口/异常检测/CheckLocalMemoryIA(ISASI).md","filePath":"api/SIMD-API/基础API/调试接口/异常检测/CheckLocalMemoryIA(ISASI).md"}'),d={name:"api/SIMD-API/基础API/调试接口/异常检测/CheckLocalMemoryIA(ISASI).md"};function r(n,t,c,i,o,h){return a(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="checklocalmemoryia-isasi" tabindex="-1">CheckLocalMemoryIA(ISASI) <a class="header-anchor" href="#checklocalmemoryia-isasi" aria-label="Permalink to &quot;CheckLocalMemoryIA\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>x</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>check设定范围内的UB读写行为，如果有设定范围的读写行为则会出现EXCEPTION报错，无设定范围的读写行为则不会报错。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void CheckLocalMemoryIA(const CheckLocalMemoryIAParam&amp; checkParams)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>checkParams</td><td>输入</td><td>用于配置对UB访问的检查行为，类型为CheckLocalMemoryIAParam。 具体定义请参考\${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_mm.h，\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。 参数说明请参考表2。</td></tr></tbody></table><p><strong>表 2</strong> CheckLocalMemoryIAParam结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>enableBit</td><td>配置的异常寄存器，取值范围：enableBit∈[0,3]，默认为0。 0：异常寄存器0。1：异常寄存器1。2：异常寄存器2。3：异常寄存器3。</td></tr><tr><td>startAddr</td><td>Check的起始地址，32B对齐，取值范围：startAddr∈[0, 65535]，默认值为0。比如，可通过LocalTensor.GetPhyAddr()/32来获取startAddr。</td></tr><tr><td>endAddr</td><td>Check的结束地址，32B对齐，取值范围：endAddr∈[0, 65535] 。默认值为0。</td></tr><tr><td>isScalarRead</td><td>Check标量读访问。 false：不开启，默认为false。true：开启。</td></tr><tr><td>isScalarWrite</td><td>Check标量写访问。 false：不开启，默认为false。true：开启。</td></tr><tr><td>isVectorRead</td><td>Check矢量读访问。 false：不开启，默认为false。true：开启。</td></tr><tr><td>isVectorWrite</td><td>Check矢量写访问。 false：不开启，默认为false。true：开启。</td></tr><tr><td>isMteRead</td><td>Check Mte读访问。 false：不开启，默认为false。true：开启。</td></tr><tr><td>isMteWrite</td><td>Check Mte写访问。 false：不开启，默认为false。true：开启。</td></tr><tr><td>isEnable</td><td>是否使能enableBit参数配置的异常寄存器。 false：不使能，默认为false。true：使能。</td></tr><tr><td>reserved</td><td>预留参数。为后续的功能做保留，开发者暂时无需关注，使用默认值即可。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>startAddr/endAddr的单位是32B，check的范围不包含startAddr，包含endAddr，即(startAddr，endAddr]。</li><li>每次调用完该接口需要进行复位（配置isEnable为false进行复位）；</li><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>该示例check矢量写访问是否在设定的(startAddr, endAddr]范围内。当前示例check到矢量写在设定的范围内，结果会报错（ACL_ERROR_RT_VECTOR_CORE_EXCEPTION）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECIN, 1&gt; inQueueSrc0, inQueueSrc1;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECOUT, 1&gt; outQueueDst</span></span>
<span class="line"><span>pipe.InitBuffer(inQueueSrc0, 1, 512 * sizeof(half));</span></span>
<span class="line"><span>pipe.InitBuffer(inQueueSrc1, 1, 512 * sizeof(half));</span></span>
<span class="line"><span>pipe.InitBuffer(outQueueDst, 1, 512 * sizeof(half));</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src0Local = inQueueSrc0.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src1Local = inQueueSrc1.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal = outQueueDst.AllocTensor&lt;half&gt;();</span></span>
<span class="line"><span>AscendC::CheckLocalMemoryIA({ 0, (uint32_t)(dstLocal.GetPhyAddr() / 32),(uint32_t)((dstLocal.GetPhyAddr() + 512 * sizeof(half)) / 32), false, false, false, true, false, false,</span></span>
<span class="line"><span>true });</span></span></code></pre></div>`,17)])])}const A=e(d,[["render",r]]);export{u as __pageData,A as default};
